 rec=db.rc.filter(c=>c.inst==t.id&&(!c.date||c.date<=E)).reduce((q,c)=>q+rcc(c).bshare,0),prj=db.pr.filter(p=>p.t==t.id&&p.status!='Cancelled'&&(!p.start||p.start<=E)).reduce((q,p)=>q+pj(p).bshare,0),
 ps=db.tp.filter(p=>p.p==t.id&&p.date<=E),pd=k=>sum(ps.filter(p=>p.src==k)),un=sum(ps.filter(p=>!p.src)),
 cats=[['Live',live],['Recorded',rec],['Project',prj],['Other',0]].map(([k,e])=>({k,earn:e,paid:pd(k),rem:e-pd(k)})),earn=live+rec+prj,paid=sum(ps);
